import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.CfX5xiXd.js";var i=JSON.parse(`{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":0}`),a={name:`faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently Asked Questions”">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to “General”">​</a></h2><details class="details custom-block"><summary>Are any extensions published right now?</summary><p>No. The built-in catalog is intentionally empty after the previously created extensions were removed.</p></details><details class="details custom-block"><summary>What extension types are supported?</summary><p>Only content extensions. Tracker and theme extension kinds are rejected by the SDK, CLI, catalog generator, and website catalog loader. This does not remove ordinary website or reader color themes.</p></details><details class="details custom-block"><summary>Does this repository include manga or comics?</summary><p>No. It publishes extension metadata and package artifacts only when an approved content extension exists. External services decide what they host, and users remain responsible for accessing only services and material they are authorized to use.</p></details><details class="details custom-block"><summary>Does adding the repository install every extension?</summary><p>No. Adding a repository makes its catalog visible to MangaReader. You still choose and review each content extension through MangaReader&#39;s install flow.</p></details><h2 id="installation-and-repositories" tabindex="-1">Installation and repositories <a class="header-anchor" href="#installation-and-repositories" aria-label="Permalink to “Installation and repositories”">​</a></h2><details class="details custom-block"><summary>What is a compatible custom catalog?</summary><p>It is an HTTP(S) directory containing <code>catalog.json</code>, or the full URL to that file. The JSON must include a <code>sources</code> array with unique source IDs, and every source must have <code>kind: &quot;content&quot;</code> or omit the kind. Tracker and theme entries cause the catalog to be rejected.</p></details><details class="details custom-block"><summary>Where are custom catalogs stored?</summary><p>Only in local storage for the current browser profile. There is no website account or cross-device synchronization.</p></details><details class="details custom-block"><summary>Why will a custom catalog not load?</summary><p>Common causes are a missing <code>catalog.json</code>, invalid JSON, duplicate source IDs, an unsupported extension kind, an HTTP error, or a server that does not allow cross-origin browser access.</p></details><h2 id="safety-and-support" tabindex="-1">Safety and support <a class="header-anchor" href="#safety-and-support" aria-label="Permalink to “Safety and support”">​</a></h2><details class="details custom-block"><summary>Are external catalogs reviewed by MangaReader?</summary><p>Not necessarily. MangaReader applies its own package and approval policy, and you should independently evaluate the publisher.</p></details><details class="details custom-block"><summary>Where should I report a security vulnerability?</summary><p>Do not open a public issue containing sensitive details. Follow the repository&#39;s <a href="https://github.com/k800k/extensions/blob/main/SECURITY.md" target="_blank" rel="noreferrer">Security Policy</a>.</p></details>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};